"""
OpenCode HTTP API client for permission management and event streaming.

Connects to OpenCode's local HTTP server to:
- Stream SSE events (permission.asked, session status, etc.)
- Reply to permission requests (allow once, always, reject)
- List pending permissions

OpenCode exposes its API on a dynamic port available via OPENCODE_PORT
env var or stored in the session registry as ``port``.
"""

from __future__ import annotations

import json
import logging
import time
from typing import Any, Generator, Optional
from urllib.error import URLError
from urllib.request import Request, urlopen

logger = logging.getLogger(__name__)


def reply_to_permission(
    port: int,
    request_id: str,
    reply: str = "once",
    host: str = "127.0.0.1",
) -> bool:
    """Reply to an OpenCode permission request.

    Args:
        port: OpenCode's HTTP server port.
        request_id: The permission request ID.
        reply: One of ``"once"``, ``"always"``, or ``"reject"``.
        host: OpenCode host (default localhost).

    Returns:
        True if the reply was sent successfully.
    """
    url = f"http://{host}:{port}/permission/{request_id}/reply"
    data = json.dumps({"reply": reply}).encode("utf-8")

    try:
        req = Request(url, data=data, method="POST")
        req.add_header("Content-Type", "application/json")
        with urlopen(req, timeout=5) as resp:
            return resp.status == 200
    except (URLError, OSError) as e:
        logger.debug("Failed to reply to permission %s: %s", request_id, e)
        return False


def list_opencode_sessions(
    port: int,
    host: str = "127.0.0.1",
) -> list[dict[str, Any]]:
    """List sessions from OpenCode's HTTP API, most recent first.

    Returns list of session dicts with id, directory, title, time, etc.
    """
    url = f"http://{host}:{port}/session"
    try:
        req = Request(url)
        req.add_header("Accept", "application/json")
        with urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            if isinstance(data, list):
                data.sort(
                    key=lambda s: s.get("time", {}).get("updated", 0),
                    reverse=True,
                )
                return data
            return []
    except (URLError, OSError, json.JSONDecodeError) as e:
        logger.debug("Failed to list OpenCode sessions: %s", e)
        return []


def create_session_with_permissions(
    port: int,
    directory: str,
    permissions: Optional[list[dict[str, str]]] = None,
    host: str = "127.0.0.1",
) -> Optional[dict[str, Any]]:
    """Create a new OpenCode session with permission rules.

    Args:
        port: OpenCode's HTTP server port.
        directory: Working directory for the session.
        permissions: Permission rules, e.g.
            ``[{"permission": "bash", "pattern": "*", "action": "ask"}]``
            If None, uses default rules requiring approval for bash, write, edit.
        host: OpenCode host.

    Returns:
        Session dict with id, directory, permission fields, or None on failure.
    """
    if permissions is None:
        permissions = [
            {"permission": "bash", "pattern": "*", "action": "ask"},
            {"permission": "write", "pattern": "*", "action": "ask"},
            {"permission": "edit", "pattern": "*", "action": "ask"},
        ]

    url = f"http://{host}:{port}/session"
    data = json.dumps(
        {
            "directory": directory,
            "permission": permissions,
        }
    ).encode("utf-8")

    try:
        req = Request(url, data=data, method="POST")
        req.add_header("Content-Type", "application/json")
        with urlopen(req, timeout=10) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except (URLError, OSError, json.JSONDecodeError) as e:
        logger.debug("Failed to create session: %s", e)
        return None


def send_opencode_message(
    port: int,
    session_id: str,
    text: str,
    host: str = "127.0.0.1",
) -> bool:
    """Send a message to an OpenCode session via the HTTP API.

    Args:
        port: OpenCode's HTTP server port.
        session_id: OpenCode's native session ID (ses_XXXX).
        text: Message text to send.
        host: OpenCode host (default localhost).

    Returns:
        True if the message was sent successfully.
    """
    url = f"http://{host}:{port}/session/{session_id}/message"
    data = json.dumps(
        {
            "parts": [{"type": "text", "text": text}],
        }
    ).encode("utf-8")

    try:
        req = Request(url, data=data, method="POST")
        req.add_header("Content-Type", "application/json")
        with urlopen(req, timeout=10) as resp:
            return resp.status == 200
    except (URLError, OSError) as e:
        logger.debug("Failed to send message to session %s: %s", session_id, e)
        return False


def list_pending_permissions(
    port: int,
    host: str = "127.0.0.1",
) -> list[dict[str, Any]]:
    """List pending permission requests from OpenCode.

    Args:
        port: OpenCode's HTTP server port.
        host: OpenCode host (default localhost).

    Returns:
        List of permission request dicts.
    """
    url = f"http://{host}:{port}/permission"

    try:
        req = Request(url)
        with urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            return data if isinstance(data, list) else []
    except (URLError, OSError, json.JSONDecodeError) as e:
        logger.debug("Failed to list permissions: %s", e)
        return []


def stream_opencode_events(
    port: int,
    session_id: Optional[str] = None,
    host: str = "127.0.0.1",
) -> Generator[dict[str, Any], None, None]:
    """Stream SSE events from OpenCode's HTTP server.

    Connects to the ``/event`` endpoint and yields parsed event dicts.
    Filters to the given session_id if provided.

    Args:
        port: OpenCode's HTTP server port.
        session_id: Optional session ID to filter events.
        host: OpenCode host (default localhost).

    Yields:
        Event dicts with ``type`` and ``properties`` keys.
    """
    url = f"http://{host}:{port}/event"
    if session_id:
        url += f"?session_id={session_id}"

    try:
        req = Request(url)
        req.add_header("Accept", "text/event-stream")
        resp = urlopen(req, timeout=30)

        buffer = ""
        while True:
            chunk = resp.read(4096)
            if not chunk:
                break
            buffer += chunk.decode("utf-8", errors="replace")

            # Parse SSE events from buffer
            while "\n\n" in buffer:
                event_str, buffer = buffer.split("\n\n", 1)
                data_lines = []
                for line in event_str.strip().split("\n"):
                    if line.startswith("data: "):
                        data_lines.append(line[6:])
                    elif line.startswith("data:"):
                        data_lines.append(line[5:])

                if data_lines:
                    try:
                        event = json.loads("".join(data_lines))
                        yield event
                    except json.JSONDecodeError:
                        pass

    except (URLError, OSError) as e:
        logger.debug("SSE stream ended: %s", e)


def watch_opencode_permissions(
    port: int,
    session_id: Optional[str] = None,
    host: str = "127.0.0.1",
    poll_interval: float = 1.0,
) -> Generator[dict[str, Any], None, None]:
    """Yield permission requests from OpenCode by polling the API.

    Falls back to polling ``/permission`` if SSE is not available.

    Args:
        port: OpenCode's HTTP server port.
        session_id: Optional session ID to filter.
        host: OpenCode host (default localhost).
        poll_interval: Seconds between polls.

    Yields:
        Permission request dicts with id, sessionID, permission, patterns, etc.
    """
    seen_ids: set[str] = set()

    while True:
        pending = list_pending_permissions(port, host)
        for perm in pending:
            perm_id = perm.get("id", "")
            perm_session = perm.get("sessionID", "")

            if perm_id in seen_ids:
                continue

            if session_id and perm_session != session_id:
                continue

            seen_ids.add(perm_id)
            yield perm

        time.sleep(poll_interval)
